using Radency.Rentals.Application.Units;

namespace Radency.Rentals.Application.Properties;

public sealed record PropertyDto(
    Guid Id,
    string Name,
    string Address,
    string City,
    int UnitCount,
    int AvailableUnitCount,
    Guid Version);

public sealed record PropertyDetailsDto(
    Guid Id,
    string Name,
    string Address,
    string City,
    IReadOnlyList<UnitDto> Units,
    Guid Version);

/// <summary>The id is generated by the client so a replayed offline request can't create a duplicate.</summary>
public sealed record CreatePropertyRequest(Guid Id, string Name, string Address, string City);

public sealed record UpdatePropertyRequest(string Name, string Address, string City, Guid Version);
